function getReminderUTC() {
  // Note: 28 March 2027 is the DST transition day in Helsinki.
  // Clocks jump from 03:00 to 04:00 EET -> EEST, so 03:30 local
  // does not exist. JS Date resolves it to 04:30 EEST (UTC +3).
  const d = new Date('2027-03-28T03:30:00'); // parsed as local time
  const reminderUTC = d.toISOString().replace('.000Z', 'Z');

  // In a real app, schedule here, e.g. setTimeout for short delays:
  const delay = d.getTime() - Date.now();
  if (delay > 0 && delay < 2147483647) {
    setTimeout(() => console.log('Reminder!'), delay);
  }
  return reminderUTC;
}

