import { Temporal } from "@js-temporal/polyfill";

function setHelsinkiReminder(onReminder) {
  const reminder = Temporal.ZonedDateTime.from(
    {
      timeZone: "Europe/Helsinki",
      year: 2027,
      month: 3,
      day: 28,
      hour: 3,
      minute: 30
    },
    { disambiguation: "reject" }
  );

  const utcISO = reminder.toInstant().toString();
  const maxDelay = 2147483647;

  function schedule() {
    const delay = reminder.epochMilliseconds - Date.now();

    if (delay <= 0) {
      onReminder(utcISO);
      return;
    }

    setTimeout(schedule, Math.min(delay, maxDelay));
  }

  schedule();
  return utcISO;
}

function reminderToUtcIso({ year, month, day, hour, minute, timeZone = "Europe/Helsinki" }) {
  // Start with a UTC guess using the requested fields, then iteratively align with the target time zone
  let utcMs = Date.UTC(year, month - 1, day, hour, minute, 0, 0);

  const formatter = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  });

  const getZonedParts = (ms) => {
    const parts = Object.fromEntries(
      formatter.formatToParts(new Date(ms))
        .filter((p) => p.type !== "literal")
        .map((p) => [p.type, Number(p.value)])
    );
    // Normalize midnight "24" if ever produced by an implementation
    const normalizedHour = parts.hour === 24 ? 0 : parts.hour;
    return { ...parts, hour: normalizedHour };
  };

  // Two passes handle standard and DST offset shifts cleanly
  for (let i = 0; i < 2; i++) {
    const actual = getZonedParts(utcMs);
    const actualAsUtc = Date.UTC(
      actual.year,
      actual.month - 1,
      actual.day,
      actual.hour,
      actual.minute,
      actual.second
    );
    const desiredAsUtc = Date.UTC(year, month - 1, day, hour, minute, 0);
    utcMs += desiredAsUtc - actualAsUtc;
  }

  // Verify the resulting instant actually formats to the requested local wall-clock time
  const verified = getZonedParts(utcMs);
  const matches =
    verified.year === year &&
    verified.month === month &&
    verified.day === day &&
    verified.hour === hour &&
    verified.minute === minute;

  if (!matches) {
    throw new Error(
      `Non-existent local time ${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")} ` +
      `${String(hour).padStart(2, "0")}:${String(minute).padStart(2, "0")} in ${timeZone} (likely a DST spring-forward gap).`
    );
  }

  return new Date(utcMs).toISOString();
}

function setReminderUtcIso() {
  return reminderToUtcIso({
    year: 2027,
    month: 3,
    day: 28,
    hour: 3,
    minute: 30,
    timeZone: "Europe/Helsinki",
  });
}

